"use strict";
const pptxgen = require("pptxgenjs");

// ─── Color Palette ───────────────────────────────────────────────────────────
// Deep crypto-dark theme: midnight navy dominant, electric teal accent
const C = {
  bg_dark:    "0B1120",   // near-black navy — dominant bg
  bg_mid:     "111827",   // slightly lighter panel bg
  bg_card:    "1A2640",   // card background
  accent:     "4EEFC9",   // electric teal/mint — primary accent
  accent2:    "7C3AED",   // violet — secondary
  gold:       "F59E0B",   // amber gold — warning / highlight
  white:      "FFFFFF",
  text_muted: "94A3B8",   // slate-400
  text_dim:   "64748B",   // slate-500
  separator:  "1E3A5F",   // subtle divider
};

// ─── Typography ──────────────────────────────────────────────────────────────
const FONT_HEAD = "Calibri";
const FONT_BODY = "Calibri";

// ─── Helpers ─────────────────────────────────────────────────────────────────
function makeShadow() {
  return { type: "outer", blur: 10, offset: 3, angle: 135, color: "000000", opacity: 0.35 };
}

function card(slide, x, y, w, h, accentColor) {
  slide.addShape("rect", {
    x, y, w, h,
    fill: { color: C.bg_card },
    shadow: makeShadow(),
    line: { color: accentColor || C.separator, width: 1 },
  });
}

function accentBar(slide, x, y, h, color) {
  slide.addShape("rect", { x, y, w: 0.07, h, fill: { color: color || C.accent }, line: { color: color || C.accent, width: 0 } });
}

function slideLabel(slide, label) {
  slide.addText(label.toUpperCase(), {
    x: 0.45, y: 0.18, w: 9.1, h: 0.22,
    fontSize: 8, fontFace: FONT_BODY, color: C.text_dim,
    charSpacing: 3, align: "left", margin: 0,
  });
}

function sectionTitle(slide, title, y) {
  slide.addText(title, {
    x: 0.45, y: y || 0.45, w: 9.1, h: 0.6,
    fontSize: 28, fontFace: FONT_HEAD, bold: true,
    color: C.white, align: "left", margin: 0,
  });
}

function bodyText(slide, text, x, y, w, h, opts) {
  slide.addText(text, {
    x, y, w, h,
    fontSize: 13, fontFace: FONT_BODY,
    color: opts?.color || C.text_muted,
    align: opts?.align || "left",
    valign: "top",
    margin: opts?.margin ?? 0,
    bold: opts?.bold || false,
    wrap: true,
    ...opts,
  });
}

function statBox(slide, value, label, x, y, w, h, accentCol) {
  card(slide, x, y, w, h, accentCol || C.accent);
  accentBar(slide, x, y, h, accentCol || C.accent);
  slide.addText(value, {
    x: x + 0.12, y: y + 0.1, w: w - 0.2, h: h * 0.55,
    fontSize: 28, fontFace: FONT_HEAD, bold: true,
    color: accentCol || C.accent, align: "left", margin: 0, wrap: true,
  });
  slide.addText(label, {
    x: x + 0.12, y: y + h * 0.62, w: w - 0.2, h: h * 0.35,
    fontSize: 11, fontFace: FONT_BODY, color: C.text_muted,
    align: "left", margin: 0, wrap: true,
  });
}

// ─── Presentation ────────────────────────────────────────────────────────────
const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.title = "Ultra Sound Money: Ethereum's Post-Merge Supply Dynamics";
pres.author = "Ultra Sound Money Analysis";

// ════════════════════════════════════════════════════════════════════════════════
// SLIDE 1 — Title Slide
// ════════════════════════════════════════════════════════════════════════════════
{
  const s = pres.addSlide();
  s.background = { color: C.bg_dark };

  // Large teal gradient block top-left
  s.addShape("rect", { x: 0, y: 0, w: 4.5, h: 5.625, fill: { color: "0D2238" }, line: { color: "0D2238" } });
  s.addShape("rect", { x: 0, y: 0, w: 0.18, h: 5.625, fill: { color: C.accent }, line: { color: C.accent } });

  // Decorative hex grid dots (decorative circles)
  for (let i = 0; i < 5; i++) {
    for (let j = 0; j < 4; j++) {
      s.addShape("ellipse", {
        x: 4.8 + i * 1.04, y: 0.5 + j * 1.25, w: 0.08, h: 0.08,
        fill: { color: C.accent, transparency: 70 }, line: { color: C.accent, transparency: 70 },
      });
    }
  }

  // ETH symbol large
  s.addText("Ξ", {
    x: 0.4, y: 0.8, w: 3.5, h: 2.2,
    fontSize: 130, fontFace: FONT_HEAD, color: C.accent,
    align: "center", margin: 0, transparency: 20,
  });

  // Title
  s.addText("ULTRA SOUND MONEY", {
    x: 4.7, y: 0.7, w: 5.0, h: 0.75,
    fontSize: 36, fontFace: FONT_HEAD, bold: true,
    color: C.white, align: "left", margin: 0, charSpacing: 2,
  });
  s.addText("Ethereum's Post-Merge Supply Dynamics\n& Monetary Premium", {
    x: 4.7, y: 1.55, w: 5.0, h: 1.0,
    fontSize: 18, fontFace: FONT_BODY, color: C.accent,
    align: "left", margin: 0,
  });

  // Divider line
  s.addShape("rect", { x: 4.7, y: 2.65, w: 4.8, h: 0.03, fill: { color: C.separator }, line: { color: C.separator } });

  // Key stats row
  const stats = [
    ["121.6M ETH", "Current Supply"],
    ["$2,243", "ETH Price (USD)"],
    ["0.1 Gwei", "Base Gas Fee"],
  ];
  stats.forEach(([val, lbl], i) => {
    const sx = 4.7 + i * 1.65;
    s.addText(val, { x: sx, y: 2.85, w: 1.55, h: 0.45, fontSize: 15, fontFace: FONT_HEAD, bold: true, color: C.accent, align: "left", margin: 0 });
    s.addText(lbl, { x: sx, y: 3.3, w: 1.55, h: 0.3, fontSize: 9, fontFace: FONT_BODY, color: C.text_dim, align: "left", margin: 0 });
  });

  // Subtitle description
  s.addText("A data-driven analysis of ETH's deflationary mechanics, burn/issuance dynamics,\nstaking economics, and how these underpin the 'ultra sound money' investment thesis.", {
    x: 4.7, y: 3.85, w: 5.0, h: 1.0,
    fontSize: 11, fontFace: FONT_BODY, color: C.text_muted,
    align: "left", margin: 0,
  });

  // Footer
  s.addText("For crypto-native investors and Ethereum ecosystem participants   |   Data: ultrasound.money", {
    x: 0.45, y: 5.2, w: 9.1, h: 0.3,
    fontSize: 9, fontFace: FONT_BODY, color: C.text_dim, align: "center", margin: 0,
  });
}

// ════════════════════════════════════════════════════════════════════════════════
// SLIDE 2 — Supply Change Snapshot
// ════════════════════════════════════════════════════════════════════════════════
{
  const s = pres.addSlide();
  s.background = { color: C.bg_dark };
  slideLabel(s, "Supply Snapshot  /  7-Day Trailing");

  sectionTitle(s, "ETH Supply Growing +0.83%/yr with Only 192 ETH Burned (7-Day)", 0.42);

  // Waterfall/bar chart: issuance vs burn
  const chartData = [
    {
      name: "ETH",
      labels: ["Issuance\n(+19,638 ETH)", "Burn\n(−192 ETH)", "Net Change\n(+19,446 ETH)"],
      values: [19638, 192, 19446],
    },
  ];
  s.addChart(pres.charts.BAR, chartData, {
    x: 0.45, y: 1.15, w: 5.5, h: 3.7,
    barDir: "col",
    chartColors: ["4EEFC9", "F59E0B", "7C3AED"],
    chartArea: { fill: { color: C.bg_card } },
    catAxisLabelColor: C.text_muted,
    valAxisLabelColor: C.text_muted,
    valGridLine: { color: "1E3A5F", size: 0.5 },
    catGridLine: { style: "none" },
    showValue: true,
    dataLabelPosition: "outEnd",
    dataLabelColor: C.white,
    dataLabelFontSize: 11,
    showLegend: false,
    showTitle: true,
    title: "7-Day ETH Issuance vs Burn",
    titleColor: C.text_muted,
    titleFontSize: 11,
  });

  // Right panel stats
  const rStats = [
    ["19,638.29 ETH", "7-Day Issuance", C.accent],
    ["192.39 ETH", "7-Day Burn", C.gold],
    ["0.01x", "Burn Offset Ratio", C.accent2],
    ["121,603,980 ETH", "Total Supply", C.text_muted],
    ["+0.83%/yr", "Annual Growth Rate", C.gold],
  ];
  rStats.forEach(([val, lbl, col], i) => {
    statBox(s, val, lbl, 6.25, 1.15 + i * 0.73, 3.3, 0.65, col);
  });

  s.addText("Burn rate suppressed by 0.1 Gwei avg gas — well below levels needed for deflation.", {
    x: 0.45, y: 4.97, w: 9.1, h: 0.35,
    fontSize: 10, fontFace: FONT_BODY, color: C.text_dim,
    italic: true, align: "left", margin: 0,
  });
}

// ════════════════════════════════════════════════════════════════════════════════
// SLIDE 3 — Gas & Burn Mechanics
// ════════════════════════════════════════════════════════════════════════════════
{
  const s = pres.addSlide();
  s.background = { color: C.bg_dark };
  slideLabel(s, "EIP-1559 Burn Mechanics  /  Gas Market");

  sectionTitle(s, "Base Gas at Historic Lows: 0.1 Gwei Average Suppresses Fee Burn", 0.42);

  // Gas range visualization
  card(s, 0.45, 1.15, 5.6, 3.7, C.accent);
  s.addText("7-Day Gas Price Range (Gwei)", {
    x: 0.6, y: 1.2, w: 5.3, h: 0.35,
    fontSize: 12, fontFace: FONT_HEAD, bold: true, color: C.accent, align: "left", margin: 0,
  });

  // Gas gauge chart using bar
  const gasData = [{ name: "Gwei", labels: ["Minimum", "Average", "Maximum", "Equilibrium\nTarget"], values: [0.0, 0.1, 1.3, 22.0] }];
  s.addChart(pres.charts.BAR, gasData, {
    x: 0.5, y: 1.6, w: 5.5, h: 3.0,
    barDir: "bar",
    chartColors: ["4EEFC9", "4EEFC9", "4EEFC9", "F59E0B"],
    chartArea: { fill: { color: C.bg_card } },
    catAxisLabelColor: C.text_muted,
    valAxisLabelColor: C.text_muted,
    valGridLine: { color: "1E3A5F", size: 0.5 },
    catGridLine: { style: "none" },
    showValue: true,
    dataLabelPosition: "outEnd",
    dataLabelColor: C.white,
    dataLabelFontSize: 11,
    showLegend: false,
    showTitle: false,
  });

  // Right panel — key data points
  const items = [
    { label: "EIP-1559 Mechanism", body: "Base fee burned on every transaction. Higher activity → higher burn → potential deflation." },
