"use strict";
const pptxgen = require("pptxgenjs");

// ─── Color Palette ───────────────────────────────────────────────────────────
// Deep crypto-dark theme: midnight navy dominant, electric teal accent
const C = {
  bg_dark:    "0B1120",   // near-black navy — dominant bg
  bg_mid:     "111827",   // slightly lighter panel bg
  bg_card:    "1A2640",   // card background
  accent:     "4EEFC9",   // electric teal/mint — primary accent
  accent2:    "7C3AED",   // violet — secondary
  gold:       "F59E0B",   // amber gold — warning / highlight
  white:      "FFFFFF",
  text_muted: "94A3B8",   // slate-400
  text_dim:   "64748B",   // slate-500
  separator:  "1E3A5F",   // subtle divider
};

// ─── Typography ──────────────────────────────────────────────────────────────
const FONT_HEAD = "Calibri";
const FONT_BODY = "Calibri";

// ─── Helpers ─────────────────────────────────────────────────────────────────
function makeShadow() {
  return { type: "outer", blur: 10, offset: 3, angle: 135, color: "000000", opacity: 0.35 };
}

function card(slide, x, y, w, h, accentColor) {
  slide.addShape("rect", {
    x, y, w, h,
    fill: { color: C.bg_card },
    shadow: makeShadow(),
    line: { color: accentColor || C.separator, width: 1 },
  });
}

function accentBar(slide, x, y, h, color) {
  slide.addShape("rect", { x, y, w: 0.07, h, fill: { color: color || C.accent }, line: { color: color || C.accent, width: 0 } });
}

function slideLabel(slide, label) {
  slide.addText(label.toUpperCase(), {
    x: 0.45, y: 0.18, w: 9.1, h: 0.22,
    fontSize: 8, fontFace: FONT_BODY, color: C.text_dim,
    charSpacing: 3, align: "left", margin: 0,
  });
}

function sectionTitle(slide, title, y) {
  slide.addText(title, {
    x: 0.45, y: y || 0.45, w: 9.1, h: 0.6,
    fontSize: 28, fontFace: FONT_HEAD, bold: true,
    color: C.white, align: "left", margin: 0,
  });
}

function bodyText(slide, text, x, y, w, h, opts) {
  slide.addText(text, {
    x, y, w, h,
    fontSize: 13, fontFace: FONT_BODY,
    color: opts?.color || C.text_muted,
    align: opts?.align || "left",
    valign: "top",
    margin: opts?.margin ?? 0,
    bold: opts?.bold || false,
    wrap: true,
    ...opts,
  });
}

function statBox(slide, value, label, x, y, w, h, accentCol) {
  card(slide, x, y, w, h, accentCol || C.accent);
  accentBar(slide, x, y, h, accentCol || C.accent);
  slide.addText(value, {
    x: x + 0.12, y: y + 0.1, w: w - 0.2, h: h * 0.55,
    fontSize: 28, fontFace: FONT_HEAD, bold: true,
    color: accentCol || C.accent, align: "left", margin: 0, wrap: true,
  });
  slide.addText(label, {
    x: x + 0.12, y: y + h * 0.62, w: w - 0.2, h: h * 0.35,
    fontSize: 11, fontFace: FONT_BODY, color: C.text_muted,
    align: "left", margin: 0, wrap: true,
  });
}

// ─── Presentation ────────────────────────────────────────────────────────────
const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.title = "Ultra Sound Money: Ethereum's Post-Merge Supply Dynamics";
pres.author = "Ultra Sound Money Analysis";

// ════════════════════════════════════════════════════════════════════════════════
// SLIDE 1 — Title Slide
// ════════════════════════════════════════════════════════════════════════════════
{
  const s = pres.addSlide();
  s.background = { color: C.bg_dark };

  // Large teal gradient block top-left
  s.addShape("rect", { x: 0, y: 0, w: 4.5, h: 5.625, fill: { color: "0D2238" }, line: { color: "0D2238" } });
  s.addShape("rect", { x: 0, y: 0, w: 0.18, h: 5.625, fill: { color: C.accent }, line: { color: C.accent } });

  // Decorative hex grid dots (decorative circles)
  for (let i = 0; i < 5; i++) {
    for (let j = 0; j < 4; j++) {
      s.addShape("ellipse", {
        x: 4.8 + i * 1.04, y: 0.5 + j * 1.25, w: 0.08, h: 0.08,
        fill: { color: C.accent, transparency: 70 }, line: { color: C.accent, transparency: 70 },
      });
    }
  }

  // ETH symbol large
  s.addText("Ξ", {
    x: 0.4, y: 0.8, w: 3.5, h: 2.2,
    fontSize: 130, fontFace: FONT_HEAD, color: C.accent,
    align: "center", margin: 0, transparency: 20,
  });

  // Title
  s.addText("ULTRA SOUND MONEY", {
    x: 4.7, y: 0.7, w: 5.0, h: 0.75,
    fontSize: 36, fontFace: FONT_HEAD, bold: true,
    color: C.white, align: "left", margin: 0, charSpacing: 2,
  });
