  rStats.forEach(([val, lbl, col], i) => {
    statBox(s, val, lbl, 6.25, 1.15 + i * 0.73, 3.3, 0.65, col);
  });

  s.addText("Burn rate suppressed by 0.1 Gwei avg gas — well below levels needed for deflation.", {
    x: 0.45, y: 4.97, w: 9.1, h: 0.35,
    fontSize: 10, fontFace: FONT_BODY, color: C.text_dim,
    italic: true, align: "left", margin: 0,
  });
}

// ════════════════════════════════════════════════════════════════════════════════
// SLIDE 3 — Gas & Burn Mechanics
// ════════════════════════════════════════════════════════════════════════════════
{
  const s = pres.addSlide();
  s.background = { color: C.bg_dark };
  slideLabel(s, "EIP-1559 Burn Mechanics  /  Gas Market");

  sectionTitle(s, "Base Gas at Historic Lows: 0.1 Gwei Average Suppresses Fee Burn", 0.42);

  // Gas range visualization
  card(s, 0.45, 1.15, 5.6, 3.7, C.accent);
  s.addText("7-Day Gas Price Range (Gwei)", {
    x: 0.6, y: 1.2, w: 5.3, h: 0.35,
    fontSize: 12, fontFace: FONT_HEAD, bold: true, color: C.accent, align: "left", margin: 0,
  });

  // Gas gauge chart using bar
  const gasData = [{ name: "Gwei", labels: ["Minimum", "Average", "Maximum", "Equilibrium\nTarget"], values: [0.0, 0.1, 1.3, 22.0] }];
  s.addChart(pres.charts.BAR, gasData, {
    x: 0.5, y: 1.6, w: 5.5, h: 3.0,
    barDir: "bar",
    chartColors: ["4EEFC9", "4EEFC9", "4EEFC9", "F59E0B"],
    chartArea: { fill: { color: C.bg_card } },
    catAxisLabelColor: C.text_muted,
