  s.addText("Low gas = low burn = temporary supply inflation. Ultra sound money thesis requires on-chain activity recovery.", {
    x: 0.45, y: 5.0, w: 9.1, h: 0.3,
    fontSize: 10, fontFace: FONT_BODY, color: C.text_dim, italic: true, align: "left", margin: 0,
  });
}

