    x: 4.7, y: 1.55, w: 5.0, h: 1.0,
    fontSize: 18, fontFace: FONT_BODY, color: C.accent,
    align: "left", margin: 0,
  });

  // Divider line
  s.addShape("rect", { x: 4.7, y: 2.65, w: 4.8, h: 0.03, fill: { color: C.separator }, line: { color: C.separator } });

  // Key stats row
  const stats = [
    ["121.6M ETH", "Current Supply"],
    ["$2,243", "ETH Price (USD)"],
    ["0.1 Gwei", "Base Gas Fee"],
  ];
  stats.forEach(([val, lbl], i) => {
    const sx = 4.7 + i * 1.65;
    s.addText(val, { x: sx, y: 2.85, w: 1.55, h: 0.45, fontSize: 15, fontFace: FONT_HEAD, bold: true, color: C.accent, align: "left", margin: 0 });
    s.addText(lbl, { x: sx, y: 3.3, w: 1.55, h: 0.3, fontSize: 9, fontFace: FONT_BODY, color: C.text_dim, align: "left", margin: 0 });
  });

  // Subtitle description
  s.addText("A data-driven analysis of ETH's deflationary mechanics, burn/issuance dynamics,\nstaking economics, and how these underpin the 'ultra sound money' investment thesis.", {
    x: 4.7, y: 3.85, w: 5.0, h: 1.0,
    fontSize: 11, fontFace: FONT_BODY, color: C.text_muted,
    align: "left", margin: 0,
  });

  // Footer
  s.addText("For crypto-native investors and Ethereum ecosystem participants   |   Data: ultrasound.money", {
    x: 0.45, y: 5.2, w: 9.1, h: 0.3,
    fontSize: 9, fontFace: FONT_BODY, color: C.text_dim, align: "center", margin: 0,
  });
}

// ════════════════════════════════════════════════════════════════════════════════
// SLIDE 2 — Supply Change Snapshot
// ════════════════════════════════════════════════════════════════════════════════
{
  const s = pres.addSlide();
  s.background = { color: C.bg_dark };
