function card(slide, x, y, w, h, accentColor) {
  slide.addShape("rect", {
    x, y, w, h,
    fill: { color: C.bg_card },
    shadow: makeShadow(),
    line: { color: accentColor || C.separator, width: 1 },
  });
}

function accentBar(slide, x, y, h, color) {
  slide.addShape("rect", {
    x, y, w: 0.07, h,
    fill: { color: color || C.accent },
    line: { color: color || C.accent, width: 0 },
