"use strict";
const pptxgen = require("pptxgenjs");

// ─── Color Palette ───────────────────────────────────────────────────────────
const C = {
  bg_dark:    "0B1120",
  bg_card:    "1A2640",
  accent:     "4EEFC9",
  accent2:    "7C3AED",
  gold:       "F59E0B",
  white:      "FFFFFF",
  text_muted: "94A3B8",
  text_dim:   "6B7FA0",
  separator:  "1E3A5F",
};

const FONT_HEAD = "Calibri";
const FONT_BODY = "Calibri";

function makeShadow() {
  return { type: "outer", blur: 8, offset: 2, angle: 135, color: "000000", opacity: 0.3 };
}

function card(slide, x, y, w, h, accentColor) {
  slide.addShape("rect", {
    x, y, w, h,
    fill: { color: C.bg_card },
    shadow: makeShadow(),
    line: { color: accentColor || C.separator, width: 1 },
  });
}

function accentBar(slide, x, y, h, color) {
  slide.addShape("rect", {
    x, y, w: 0.07, h,
    fill: { color: color || C.accent },
    line: { color: color || C.accent, width: 0 },
  });
}

function slideLabel(slide, label) {
  slide.addText(label.toUpperCase(), {
    x: 0.45, y: 0.18, w: 9.1, h: 0.22,
    fontSize: 8, fontFace: FONT_BODY, color: C.text_dim,
    charSpacing: 3, align: "left", margin: 0,
  });
}

function sectionTitle(slide, title, y) {
  slide.addText(title, {
    x: 0.45, y: y || 0.43, w: 9.1, h: 0.65,
    fontSize: 22, fontFace: FONT_HEAD, bold: true,
    color: C.white, align: "left", margin: 0,
  });
}

// Stat box with value+label that won't overflow — sized for content
function statBox(slide, value, label, x, y, w, accentCol) {
  const h = 0.68;
  card(slide, x, y, w, h, accentCol || C.accent);
  accentBar(slide, x, y, h, accentCol || C.accent);
  slide.addText(value, {
    x: x + 0.13, y: y + 0.07, w: w - 0.22, h: 0.32,
    fontSize: 18, fontFace: FONT_HEAD, bold: true,
    color: accentCol || C.accent, align: "left", margin: 0, wrap: false,
  });
  slide.addText(label, {
    x: x + 0.13, y: y + 0.38, w: w - 0.22, h: 0.26,
    fontSize: 10, fontFace: FONT_BODY, color: C.text_muted,
    align: "left", margin: 0, wrap: true,
  });
}

function footerNote(slide, text) {
  slide.addShape("rect", { x: 0, y: 5.27, w: 10, h: 0.355, fill: { color: "0A1628" }, line: { color: "0A1628" } });
  slide.addText(text, {
    x: 0.45, y: 5.29, w: 9.1, h: 0.3,
    fontSize: 9, fontFace: FONT_BODY, color: "7A94C0",
    italic: true, align: "center", margin: 0,
  });
}

// ─── Presentation ────────────────────────────────────────────────────────────
const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.title = "Ultra Sound Money: Ethereum Post-Merge Supply Dynamics";
pres.author = "Ultra Sound Money Analysis";

// ════════════════════════════════════════════════════════════════════════════════
// SLIDE 1 — Title Slide
// ════════════════════════════════════════════════════════════════════════════════
{
  const s = pres.addSlide();
  s.background = { color: C.bg_dark };

  // Left accent panel
  s.addShape("rect", { x: 0, y: 0, w: 4.4, h: 5.625, fill: { color: "0D2238" }, line: { color: "0D2238" } });
  s.addShape("rect", { x: 0, y: 0, w: 0.2, h: 5.625, fill: { color: C.accent }, line: { color: C.accent } });

  // ETH symbol — left panel center (large but no dot overlay)
  s.addText("Ξ", {
    x: 0.3, y: 0.6, w: 3.8, h: 3.5,
    fontSize: 180, fontFace: FONT_HEAD, color: "0F3A52",
    align: "center", margin: 0,
  });
  // Bright ETH text on top
  s.addText("Ξ", {
    x: 0.3, y: 0.9, w: 3.8, h: 2.8,
    fontSize: 120, fontFace: FONT_HEAD, color: C.accent,
    align: "center", margin: 0,
  });

  // Title
  s.addText("ULTRA SOUND MONEY", {
    x: 4.6, y: 0.65, w: 5.0, h: 0.65,
    fontSize: 34, fontFace: FONT_HEAD, bold: true,
    color: C.white, align: "left", margin: 0, charSpacing: 1.5,
  });
  s.addText("Ethereum's Post-Merge Supply Dynamics\n& Monetary Premium", {
    x: 4.6, y: 1.42, w: 5.0, h: 0.85,
    fontSize: 17, fontFace: FONT_BODY, color: C.accent,
    align: "left", margin: 0,
  });

  // Divider
  s.addShape("rect", { x: 4.6, y: 2.42, w: 4.9, h: 0.03, fill: { color: C.separator }, line: { color: C.separator } });

  // Key stats — 3 columns
  const stats = [
    ["121.6M ETH", "Current Supply"],
    ["$2,243", "ETH Price (USD)"],
    ["0.1 Gwei", "Avg Base Gas"],
  ];
  stats.forEach(([val, lbl], i) => {
    const sx = 4.6 + i * 1.65;
    s.addText(val, {
      x: sx, y: 2.58, w: 1.55, h: 0.42,
      fontSize: 16, fontFace: FONT_HEAD, bold: true, color: C.accent, align: "left", margin: 0,
    });
    s.addText(lbl, {
      x: sx, y: 2.99, w: 1.55, h: 0.27,
      fontSize: 9.5, fontFace: FONT_BODY, color: C.text_muted, align: "left", margin: 0,
    });
  });

  // Description
  s.addText("A data-driven analysis of ETH's deflationary mechanics, burn/issuance\ndynamics, staking economics, and the long-run 'ultra sound money' thesis.", {
    x: 4.6, y: 3.5, w: 5.0, h: 0.85,
    fontSize: 11.5, fontFace: FONT_BODY, color: C.text_muted, align: "left", margin: 0,
  });

  // Audience badge
  s.addShape("rect", { x: 4.6, y: 4.5, w: 4.9, h: 0.38, fill: { color: "0F3A52" }, line: { color: C.accent } });
  s.addText("For crypto-native investors and Ethereum ecosystem participants evaluating ETH as a monetary asset", {
    x: 4.65, y: 4.53, w: 4.8, h: 0.32,
    fontSize: 9.5, fontFace: FONT_BODY, color: C.text_muted, align: "left", margin: 0, wrap: true,
  });

  footerNote(s, "Data: ultrasound.money");
}

// ════════════════════════════════════════════════════════════════════════════════
// SLIDE 2 — Supply Change Snapshot
// ════════════════════════════════════════════════════════════════════════════════
{
  const s = pres.addSlide();
  s.background = { color: C.bg_dark };
  slideLabel(s, "Supply Snapshot  /  7-Day Trailing");
  sectionTitle(s, "ETH Supply Growing +0.83%/yr — Burn Offsets Only ~1% of Issuance (7-Day)");

  // Bar chart — issuance vs burn only (2 bars, clearer comparison)
  s.addChart(pres.charts.BAR, [{
    name: "ETH",
    labels: ["Issuance\n(+19,638 ETH)", "Burn\n(−192 ETH)"],
    values: [19638, 192],
  }], {
    x: 0.45, y: 1.2, w: 5.5, h: 3.65,
    barDir: "col",
    barGapWidthPct: 80,
    chartColors: ["4EEFC9", "F59E0B"],
    chartArea: { fill: { color: C.bg_card } },
    catAxisLabelColor: "94A3B8",
    valAxisLabelColor: "94A3B8",
    valGridLine: { color: "1E3A5F", size: 0.5 },
    catGridLine: { style: "none" },
    showValue: true,
    dataLabelPosition: "outEnd",
    dataLabelColor: "FFFFFF",
    dataLabelFontSize: 13,
    showLegend: false,
    showTitle: true,
    title: "7-Day: Issuance vs Burn (ETH)",
    titleColor: "94A3B8",
    titleFontSize: 10,
  });

  // Stat boxes — right column, 5 items, equally spaced, with margin from edge
  const rStats = [
    ["19,638 ETH", "7-Day Issuance", C.accent],
    ["192 ETH", "7-Day Burn", C.gold],
    ["0.01x", "Burn Offset Ratio", C.accent2],
    ["121.6M ETH", "Total Supply", C.text_muted],
    ["+0.83%/yr", "Annual Growth Rate", C.gold],
  ];
  const rbx = 6.2, rbw = 3.3;
  rStats.forEach(([val, lbl, col], i) => {
    statBox(s, val, lbl, rbx, 1.2 + i * 0.74, rbw, col);
  });

  footerNote(s, "Burn rate suppressed by 0.1 Gwei avg gas — well below levels needed for deflation. Burn offset ratio: burns ÷ issuance = 0.01x.");
}

// ════════════════════════════════════════════════════════════════════════════════
// SLIDE 3 — Gas & Burn Mechanics
// ════════════════════════════════════════════════════════════════════════════════
{
  const s = pres.addSlide();
  s.background = { color: C.bg_dark };
  slideLabel(s, "EIP-1559 Burn Mechanics  /  Gas Market");
  sectionTitle(s, "Base Gas at Historic Lows: 0.1 Gwei Average Suppresses Fee Burn");

  // Gas range bar chart — log-style labels to make small values readable
  s.addChart(pres.charts.BAR, [{
    name: "Gwei",
    labels: ["Min (0.0 Gwei)", "Avg (0.1 Gwei)", "Max (1.3 Gwei)", "Equil. Target\n(22 Gwei)"],
    values: [0.01, 0.1, 1.3, 22.0],
  }], {
    x: 0.45, y: 1.2, w: 5.5, h: 3.65,
    barDir: "bar",
    barGapWidthPct: 50,
    chartColors: ["4EEFC9", "4EEFC9", "4EEFC9", "F59E0B"],
    chartArea: { fill: { color: C.bg_card } },
    catAxisLabelColor: "94A3B8",
    valAxisLabelColor: "94A3B8",
    valGridLine: { color: "1E3A5F", size: 0.5 },
    catGridLine: { style: "none" },
    showValue: true,
    dataLabelPosition: "outEnd",
    dataLabelColor: "FFFFFF",
    dataLabelFontSize: 12,
    showLegend: false,
    showTitle: true,
    title: "7-Day Gas Price Range (Gwei)  —  Gold = Equilibrium Target",
    titleColor: "94A3B8",
    titleFontSize: 9,
  });

  // Right column info cards
  const items = [
    { label: "EIP-1559 Mechanism", body: "Base fee burned on every tx. Higher activity → higher burn → deflation potential.", col: C.accent },
    { label: "Current Avg Gas", body: "0.1 Gwei (7-day avg). Min: 0.0 Gwei, Max: 1.3 Gwei. Near all-time lows.", col: C.accent },
    { label: "Blob Fees (EIP-4844)", body: "Only 0.15 ETH (~$319) in blob fees burned over 7 days. Avg blob gas: 7,144,934 wei.", col: C.accent2 },
    { label: "Equilibrium Requires", body: "Sustained ~22 Gwei avg to balance issuance with burn at ~1,037K ETH/year.", col: C.gold },
  ];
  items.forEach((item, i) => {
    const cy = 1.2 + i * 0.92;
    const h = 0.83;
    card(s, 6.2, cy, 3.35, h, item.col);
    accentBar(s, 6.2, cy, h, item.col);
    s.addText(item.label, {
      x: 6.37, y: cy + 0.08, w: 3.08, h: 0.28,
      fontSize: 11, fontFace: FONT_HEAD, bold: true, color: C.white, align: "left", margin: 0,
    });
    s.addText(item.body, {
      x: 6.37, y: cy + 0.38, w: 3.08, h: 0.4,
      fontSize: 9.5, fontFace: FONT_BODY, color: C.text_muted, align: "left", margin: 0, wrap: true,
    });
  });

  footerNote(s, "Low gas = low burn = temporary supply inflation. Ultra sound money thesis requires on-chain activity recovery to ~22 Gwei sustained.");
}

// ════════════════════════════════════════════════════════════════════════════════
// SLIDE 4 — Burn Leaderboard & Categories
// ════════════════════════════════════════════════════════════════════════════════
{
  const s = pres.addSlide();
  s.background = { color: C.bg_dark };
  slideLabel(s, "Fee Burn Categories  /  Leaderboard  /  7-Day");
  sectionTitle(s, "DeFi & ETH Transfers Drive ~85% of 192 ETH in Weekly Fee Burn");

  // Horizontal bar chart — categories (ascending for better visual)
  s.addChart(pres.charts.BAR, [{
    name: "ETH Burned",
    labels: ["Contract Creation", "NFTs", "Misc", "ETH Transfers", "DeFi"],
    values: [2, 3, 4, 22, 31],
  }], {
    x: 0.45, y: 1.2, w: 5.5, h: 3.35,
    barDir: "bar",
    barGapWidthPct: 40,
    chartColors: ["4EEFC9"],
    chartArea: { fill: { color: C.bg_card } },
    catAxisLabelColor: "94A3B8",
    valAxisLabelColor: "94A3B8",
    valGridLine: { color: "1E3A5F", size: 0.5 },
    catGridLine: { style: "none" },
    showValue: true,
    dataLabelPosition: "outEnd",
    dataLabelColor: "FFFFFF",
    dataLabelFontSize: 12,
    showLegend: false,
    showTitle: true,
    title: "Burn by Category — ETH (7-Day)   |   L2, MEV, Blobs = 0 ETH",
    titleColor: "94A3B8",
    titleFontSize: 9,
  });

  // Leaderboard on right
  s.addText("TOP CONTRIBUTORS (7-DAY)", {
    x: 6.2, y: 1.2, w: 3.35, h: 0.3,
    fontSize: 8.5, fontFace: FONT_HEAD, bold: true, color: C.accent,
    charSpacing: 2, align: "left", margin: 0,
  });

  const leaders = [
    ["ETH Transfers", "21.74 ETH"],
    ["Tether USDT", "13.55 ETH"],
    ["DeFi (total)", "~31 ETH"],
    ["NFT Contracts", "~3 ETH"],
