"use strict";
const pptxgen = require("pptxgenjs");

// ─── Color Palette ───────────────────────────────────────────────────────────
const C = {
  bg_dark:    "0B1120",
  bg_card:    "1A2640",
  accent:     "4EEFC9",
  accent2:    "7C3AED",
  gold:       "F59E0B",
  white:      "FFFFFF",
  text_muted: "94A3B8",
  text_dim:   "6B7FA0",
  separator:  "1E3A5F",
};

const FONT_HEAD = "Calibri";
const FONT_BODY = "Calibri";

function makeShadow() {
  return { type: "outer", blur: 8, offset: 2, angle: 135, color: "000000", opacity: 0.3 };
}

function card(slide, x, y, w, h, accentColor) {
  slide.addShape("rect", {
    x, y, w, h,
    fill: { color: C.bg_card },
    shadow: makeShadow(),
    line: { color: accentColor || C.separator, width: 1 },
  });
}

function accentBar(slide, x, y, h, color) {
  slide.addShape("rect", {
    x, y, w: 0.07, h,
    fill: { color: color || C.accent },
    line: { color: color || C.accent, width: 0 },
  });
}

function slideLabel(slide, label) {
  slide.addText(label.toUpperCase(), {
    x: 0.45, y: 0.18, w: 9.1, h: 0.22,
    fontSize: 8, fontFace: FONT_BODY, color: C.text_dim,
    charSpacing: 3, align: "left", margin: 0,
  });
}

function sectionTitle(slide, title, y) {
  slide.addText(title, {
    x: 0.45, y: y || 0.43, w: 9.1, h: 0.65,
    fontSize: 22, fontFace: FONT_HEAD, bold: true,
    color: C.white, align: "left", margin: 0,
  });
}

// Stat box with value+label that won't overflow — sized for content
function statBox(slide, value, label, x, y, w, accentCol) {
  const h = 0.68;
  card(slide, x, y, w, h, accentCol || C.accent);
  accentBar(slide, x, y, h, accentCol || C.accent);
  slide.addText(value, {
    x: x + 0.13, y: y + 0.07, w: w - 0.22, h: 0.32,
    fontSize: 18, fontFace: FONT_HEAD, bold: true,
    color: accentCol || C.accent, align: "left", margin: 0, wrap: false,
  });
  slide.addText(label, {
    x: x + 0.13, y: y + 0.38, w: w - 0.22, h: 0.26,
    fontSize: 10, fontFace: FONT_BODY, color: C.text_muted,
    align: "left", margin: 0, wrap: true,
  });
}

function footerNote(slide, text) {
  slide.addShape("rect", { x: 0, y: 5.27, w: 10, h: 0.355, fill: { color: "0A1628" }, line: { color: "0A1628" } });
  slide.addText(text, {
    x: 0.45, y: 5.29, w: 9.1, h: 0.3,
    fontSize: 9, fontFace: FONT_BODY, color: "7A94C0",
    italic: true, align: "center", margin: 0,
  });
}

